#!/usr/bin/env bash
# Installe le hook pre-push de garde de confidentialité.
set -euo pipefail

MARKER="# GENERATED BY agentic-cockpit install-hooks.sh"

COMMON_DIR="$(git rev-parse --git-common-dir)"
HOOKS_DIR="${COMMON_DIR}/hooks"
HOOK_PATH="${HOOKS_DIR}/pre-push"

mkdir -p "${HOOKS_DIR}"

if [ -e "${HOOK_PATH}" ]; then
    if ! grep -qF "${MARKER}" "${HOOK_PATH}" 2>/dev/null; then
        echo "Erreur : un hook pre-push non généré par install-hooks.sh existe déjà (${HOOK_PATH})." >&2
        exit 1
    fi
fi

cat > "${HOOK_PATH}" <<'EOF'
#!/usr/bin/env bash
# GENERATED BY agentic-cockpit install-hooks.sh
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
CONFIG_DIR="${COCKPIT_CONFIG_DIR:-$HOME/.config/agentic-cockpit}"
PROJECT_ARGS=()
if [ -f "${CONFIG_DIR}/projects.toml" ]; then
    PROJECT_ID="$(python3 - "${CONFIG_DIR}/projects.toml" "${REPO_ROOT}" <<'PY'
import sys, tomllib
from pathlib import Path
try:
    data = tomllib.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
except Exception:
    sys.exit(0)
repo = Path(sys.argv[2]).resolve()
for pid, conf in data.get("projects", {}).items():
    root = conf.get("root") if isinstance(conf, dict) else None
    if root and Path(root).expanduser().resolve() == repo:
        print(pid)
        break
PY
)"
    if [ -n "${PROJECT_ID}" ]; then PROJECT_ARGS=(--project "${PROJECT_ID}"); fi
fi

while read -r local_ref local_sha remote_ref remote_sha; do
    [ -z "${local_sha:-}" ] && continue
    python3 "${REPO_ROOT}/scripts/privacy-check.py" --repo "${REPO_ROOT}" ${PROJECT_ARGS[@]+"${PROJECT_ARGS[@]}"} --range "${remote_sha}..${local_sha}"
done
EOF

chmod +x "${HOOK_PATH}"
